# Used by the interpretability harness.
def interpretability_hex_word_sum(string):
    string = string.replace('O', '0')
    string = string.replace('S', '5')
    new = string.split()
    sum = 0
    for i in new:
        try:
            interpretability_v = int(i, 17)
        except:
            interpretability_v = 1
        sum = sum + interpretability_v
    return sum

